public static String numbersTo100() {
    String s = "";
    for (int i = 1; i <= 100; i++) {
        s = s + i + " ";
    }
    return s;
}

public static String evensTo100() {
    String s = "";
    for (int i = 2; i <= 100; i = i + 2) {
        s = s + i + " ";
    }
    return s;
}

public static String evensDown() {
    String s = "";
    for (int i = 100; i >= 2; i = i - 2) {
        s = s + i + " ";
    }
    return s;
}

public static String divisibleBy(int k) {
    String s = "";
    for (int i = k; i <= 100; i = i + k) {   // רק הכפולות של k
        s = s + i + " ";
    }
    return s;
}

public static String fromTo(int m, int n) {
    String s = "";
    if (m <= n) {
        for (int i = m; i <= n; i++) {
            s = s + i + " ";
        }
    } else {
        for (int i = m; i >= n; i--) {
            s = s + i + " ";
        }
    }
    return s;
}

